class Solution {
public:
    int houseCount(Street* street, int k) {
        while (!street->isDoorOpen()) {
            street->moveRight();
        }
        street->moveRight();
        int ans = 0;
        for (int count = 1; count <= k; ++count) {
            if (street->isDoorOpen()) {
                ans = count;
                street->closeDoor();
            }
            street->moveRight();
        }
        return ans;
    }
};

